SELECT  FROM agent


        AND name LIKE CONCAT('%', #{query}, '%')


        AND status = #{isPublished}


        AND agent_type = #{agentType}


ORDER BY create_time DESC

mapper.update:
UPDATE agent
name = #{name}, config = #{config}, status = #{status}, agent_type = #{agentType}, memory_schema = #{memorySchema}, reference_turns = #{referenceTurns}, updater = #{updater}, update_time = NOW()
WHERE app_id = #{appId}
